import sys
import sqlite3
import xml.etree.ElementTree as ET
import json
import base64
import re
from io import StringIO

def extract_cert_serial(cert_pem):
    try:
        cert_bytes = cert_pem.encode('utf-8')
        cert_data = base64.b64decode(cert_bytes)
        cert_der = cert_data[:20]  # First 20 bytes for serial number
        serial = int.from_bytes(cert_der, byteorder='big')
        return f"{serial:0x}" if serial != 0 else "0"
    except:
        return None

def process_cert_value(value):
    if value is None:
        return None
    if isinstance(value, str):
        try:
            cert_pem = value.strip()
            if re.match(r'-----BEGIN CERTIFICATE-----.*-----END CERTIFICATE-----', cert_pem, re.IGNORECASE):
                return extract_cert_serial(cert_pem)
        except:
            pass
    return value

