        # Get column names
        columns = [desc[0] for desc in cursor.description]
        if 'certificate' in columns:
            columns = [col if col != 'certificate' else 'cert_serial' for col in columns]

        # Fetch results
        results = cursor.fetchall()
        output = StringIO()
