import sys
import sqlite3
import json
import xml.etree.ElementTree as ET
import csv
import base64
import re

def parse_xml_config(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    db_name = root.find('database').text
    queries = {}
    for query_elem in root.findall('query'):
        name = query_elem.get('name')
        sql = query_elem.text.strip()
        queries[name] = sql
    return db_name, queries

def parse_json_params(params_path):
    with open(params_path, 'r') as f:
        return json.load(f)

def process_certificate(value):
    if value is None:
        return value
    if not isinstance(value, str):
        return value
    try:
        # Check if the string is a valid PEM-encoded certificate
        if re.match(r'-----BEGIN CERTIFICATE-----', value, re.IGNORECASE):
            # Extract the serial number from the certificate
            cert_data = value.encode('utf-8')
            cert_bytes = base64.b64decode(cert_data)
            # The serial number is the first 4 bytes in little-endian format
            serial = cert_bytes[:4]
            return f"{int.from_bytes(serial, byteorder='little', signed=False):x}".lower()
        return value
    except:
        return value

def execute_query(db_name, query_name, sql, params):
    conn = sqlite3.connect(db_name)
    cursor = conn.cursor()
    try:
        cursor.execute(sql, params)
        columns = [desc[0] for desc in cursor.description]
        rows = cursor.fetchall()
        conn.close()
        return columns, rows
    except sqlite3.Error as e:
        print(f"Database error: {e}", file=sys.stderr)
        sys.exit(1)

def main():
    if len(sys.argv) != 4:
        print("Usage: python run_query.py <config.xml> <params.json> <query_name>", file=sys.stderr)
        sys.exit(2)

    xml_path = sys.argv[1]
    params_path = sys.argv[2]
    query_name = sys.argv[3]

    try:
        db_name, queries = parse_xml_config(xml_path)
        if query_name not in queries:
            print("query not found", file=sys.stderr)
            sys.exit(2)

        params = parse_json_params(params_path)
        sql = queries[query_name]

        columns, rows = execute_query(db_name, query_name, sql, params)

        # Prepare CSV output
        writer = csv.writer(sys.stdout)
        writer.writerow(columns)

        for row in rows:
            processed_row = []
            for value in row:
                if columns.index('certificate') == len(processed_row):
                    processed_value = process_certificate(value)
                    processed_row.append(processed_value)
                else:
                    processed_row.append(value)
            writer.writerow(processed_row)

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import sqlite3
import json
import xml.etree.ElementTree as ET
import base64
import re
from typing import Dict, List, Any, Optional

def extract_cert_serial(cert_str: str) -> Optional[str]:
    if not cert_str or not isinstance(cert_str, str):
        return None
    try:
        # Extract the ASN.1 DER encoded certificate
        der_data = base64.b64decode(cert_str)
        # Simple check for ASN.1 DER certificate (adjust regex as needed)
        if re.match(b'^\x30[0-9a-f]{2,}$', der_data[:2]):
            # Extract serial number (simplified; actual parsing would require ASN.1 parsing)
            # This is a placeholder for actual ASN.1 parsing logic
            serial_bytes = der_data[0x13:0x17]  # Example: first 4 bytes after SEQUENCE
            serial_hex = serial_bytes.hex().lower()
            return serial_hex if serial_hex else '0'
    except:
        return None
    return None

def process_certificate_value(value: Any) -> str:
    if value is None:
        return ''
    if isinstance(value, str):
        cert_serial = extract_cert_serial(value)
        if cert_serial:
            return cert_serial
    return str(value)

def run_query():
    if len(sys.argv) != 4:
        print("Usage: python run_query.py config.xml params.json query_name", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]
    json_path = sys.argv[2]
    query_name = sys.argv[3]

    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except ET.ParseError:
        print("Invalid XML configuration file", file=sys.stderr)
        sys.exit(1)

    db_name = None
    query_element = None

    for elem in root.iter():
        if elem.tag == 'database':
            db_name = elem.text
        elif elem.tag == 'query' and elem.attrib.get('name') == query_name:
            query_element = elem

    if not db_name or not query_element:
        print("query not found", file=sys.stderr)
        sys.exit(2)

    try:
        with sqlite3.connect(db_name) as conn:
            cursor = conn.cursor()
            sql = query_element.text
            params = json.load(open(json_path))

            # Bind parameters
            param_bindings = {}
            for key, value in params.items():
                param_bindings[f":{key}"] = value

            # Prepare cursor with parameter bindings
            cursor.execute(sql, param_bindings)

            # Get column names
            columns = [desc[0] for desc in cursor.description]
            header = ','.join(columns)

            # Process results
            rows = cursor.fetchall()
            processed_rows = []
            for row in rows:
                processed_row = []
                for i, value in enumerate(row):
                    processed_value = process_certificate_value(value)
                    processed_row.append(processed_value)
                processed_rows.append(processed_row)

            # Write CSV output
            print(header)
            for row in processed_rows:
                print(','.join(str(cell) for cell in row))

    except sqlite3.Error as e:
        print(f"Database error: {e}", file=sys.stderr)
        sys.exit(1)
    except json.JSONDecodeError:
        print("Invalid JSON parameters file", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    run_query()
